"""Terrain analysis of a gridded bathymetric surface.

Given a regular grid of cell mean depths (as produced by
:func:`ocean_sonar.grid.build`), derive per-cell slope and roughness.
Slope is the gradient angle in degrees from the four direct neighbours;
roughness is the ``max - min`` spread of the non-empty means in the
boundary-clipped 3x3 neighbourhood.
"""

from __future__ import annotations

import math

from .svp import _is_real_number

__all__ = ["analyze"]


def _round6(value):
    result = round(float(value), 6)
    if result == 0:
        result = 0.0
    return result


def analyze(r, nx, ny, cells):
    """Compute per-cell slope and roughness for a regular depth grid.

    ``r`` is the cell size, a finite non-bool int/float with ``r > 0``.
    ``nx``/``ny`` are non-bool positive ints. ``cells`` is a list/tuple
    of length ``nx * ny`` ordered by ``y`` then ``x``; each item is a
    two-element list/tuple ``(count, mean)`` where ``count`` is a
    non-bool non-negative int, ``mean`` is exactly ``None`` when
    ``count == 0`` and a finite non-bool int/float ``>= 0`` otherwise.

    For a non-empty cell, roughness is ``max - min`` over the non-empty
    means of the 3x3 neighbourhood clipped to the grid bounds. With
    left/right/down/up neighbour means ``L``/``R``/``D``/``U`` all
    present and non-empty, slope is
    ``degrees(atan(hypot((R - L) / (2 * r), (U - D) / (2 * r))))``;
    otherwise slope is ``None``. Empty cells are fixed as
    ``(None, None)``.

    Validation follows the signature parameter order and then grid
    order, stopping at the first error: type mismatches (including
    bool) raise ``TypeError``, all other constraint errors raise
    ``ValueError``. Cell errors are prefixed with ``"cells[i]: "``.

    Returns a tuple in the same order and length as ``cells`` of
    ``(slope, roughness)`` pairs; non-``None`` values are rounded with
    ``round(float(v), 6)`` (negative zero normalized to ``0.0``). All
    computation uses the unrounded means; inputs are not modified.
    """
    if not _is_real_number(r):
        raise TypeError("r must be a non-bool int or float")
    if not math.isfinite(r):
        raise ValueError("r must be finite")
    if not r > 0:
        raise ValueError("r must be > 0")

    for name, value in (("nx", nx), ("ny", ny)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{name} must be a non-bool int")
        if not value > 0:
            raise ValueError(f"{name} must be > 0")

    if not isinstance(cells, (list, tuple)):
        raise TypeError("cells must be a list or tuple")
    if len(cells) != nx * ny:
        raise ValueError("cells must have nx * ny elements")

    for i in range(len(cells)):
        prefix = f"cells[{i}]: "
        cell = cells[i]
        if not isinstance(cell, (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(cell) != 2:
            raise ValueError(prefix + "must have 2 elements")
        count, mean = cell
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError(prefix + "count must be a non-bool int")
        if not count >= 0:
            raise ValueError(prefix + "count must be >= 0")
        if count == 0:
            if mean is not None:
                raise ValueError(prefix + "mean must be None when count is 0")
        else:
            if not _is_real_number(mean):
                raise TypeError(prefix + "mean must be a non-bool int or float")
            if not math.isfinite(mean):
                raise ValueError(prefix + "mean must be finite")
            if not mean >= 0:
                raise ValueError(prefix + "mean must be >= 0")

    means = [cell[1] if cell[0] > 0 else None for cell in cells]

    def mean_at(ix, iy):
        if 0 <= ix < nx and 0 <= iy < ny:
            return means[iy * nx + ix]
        return None

    result = []
    for iy in range(ny):
        for ix in range(nx):
            center = means[iy * nx + ix]
            if center is None:
                result.append((None, None))
                continue

            low = high = center
            for jy in range(max(0, iy - 1), min(ny, iy + 2)):
                for jx in range(max(0, ix - 1), min(nx, ix + 2)):
                    value = means[jy * nx + jx]
                    if value is None:
                        continue
                    if value < low:
                        low = value
                    if value > high:
                        high = value
            roughness = _round6(high - low)

            left = mean_at(ix - 1, iy)
            right = mean_at(ix + 1, iy)
            down = mean_at(ix, iy - 1)
            up = mean_at(ix, iy + 1)
            if None in (left, right, down, up):
                slope = None
            else:
                slope = _round6(
                    math.degrees(
                        math.atan(
                            math.hypot(
                                (right - left) / (2 * r),
                                (up - down) / (2 * r),
                            )
                        )
                    )
                )
            result.append((slope, roughness))
    return tuple(result)

"""Quality assessment of gridded terrain-analysis layers.

Given per-layer ``(r, nx, ny, analysis)`` descriptions where each
analysis cell is a ``(slope, roughness)`` pair as produced by
:func:`ocean_sonar.terrain.analyze`, summarize coverage and the counts
of cells whose slope/roughness strictly exceed the given limits.
"""

from __future__ import annotations

import math

from .svp import _is_real_number

__all__ = ["assess"]


def _round6(value):
    result = round(float(value), 6)
    if result == 0:
        result = 0.0
    return result


def assess(layers, slope_limit=5.0, roughness_limit=1.0):
    """Assess coverage and limit exceedance per terrain layer.

    ``layers`` is a non-empty list/tuple of ``(r, nx, ny, analysis)``
    items: ``r`` is a finite non-bool int/float ``> 0``; ``nx``/``ny``
    are non-bool positive ints; ``analysis`` is a list/tuple of length
    ``nx * ny`` whose items are two-element list/tuples
    ``(slope, roughness)``. A cell is either exactly ``(None, None)``
    (empty), or ``slope`` is ``None`` or a finite non-bool int/float
    ``>= 0`` and ``roughness`` is a finite non-bool int/float ``>= 0``.
    ``slope_limit``/``roughness_limit`` are finite non-bool int/float
    values ``> 0``.

    Validation follows the signature parameter order, then layer and
    cell index order, then field order, stopping at the first error:
    type mismatches (including bool) raise ``TypeError``, all other
    constraint errors raise ``ValueError``. Layer errors are prefixed
    with ``"layers[i]: "`` and cell errors with
    ``"layers[i].analysis[j]: "``.

    Returns a tuple in the same order as ``layers``; each item is a
    dict with keys ``resolution, total, valid, coverage,
    slope_exceed, roughness_exceed``. ``total`` is ``nx * ny``,
    ``valid`` counts non-empty cells and ``coverage`` is
    ``valid / total``. Exceedance counts use strict ``>`` and ignore
    ``None``. Counts are ints; the other values are
    ``round(float(v), 6)`` (negative zero normalized to ``0.0``).
    Inputs are not modified.
    """
    if not isinstance(layers, (list, tuple)):
        raise TypeError("layers must be a list or tuple")
    if len(layers) == 0:
        raise ValueError("layers must be non-empty")

    for i in range(len(layers)):
        prefix = f"layers[{i}]: "
        layer = layers[i]
        if not isinstance(layer, (list, tuple)):
            raise TypeError(prefix + "must be a list or tuple")
        if len(layer) != 4:
            raise ValueError(prefix + "must have 4 elements")
        r, nx, ny, analysis = layer

        if not _is_real_number(r):
            raise TypeError(prefix + "r must be a non-bool int or float")
        if not math.isfinite(r):
            raise ValueError(prefix + "r must be finite")
        if not r > 0:
            raise ValueError(prefix + "r must be > 0")

        for name, value in (("nx", nx), ("ny", ny)):
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(prefix + f"{name} must be a non-bool int")
            if not value > 0:
                raise ValueError(prefix + f"{name} must be > 0")

        if not isinstance(analysis, (list, tuple)):
            raise TypeError(prefix + "analysis must be a list or tuple")
        if len(analysis) != nx * ny:
            raise ValueError(prefix + "analysis must have nx * ny elements")

        for j in range(len(analysis)):
            cell_prefix = f"layers[{i}].analysis[{j}]: "
            cell = analysis[j]
            if not isinstance(cell, (list, tuple)):
                raise TypeError(cell_prefix + "must be a list or tuple")
            if len(cell) != 2:
                raise ValueError(cell_prefix + "must have 2 elements")
            slope, roughness = cell
            if slope is None and roughness is None:
                continue
            if slope is not None:
                if not _is_real_number(slope):
                    raise TypeError(
                        cell_prefix + "slope must be None or a non-bool int or float"
                    )
                if not math.isfinite(slope):
                    raise ValueError(cell_prefix + "slope must be finite")
                if not slope >= 0:
                    raise ValueError(cell_prefix + "slope must be >= 0")
            if not _is_real_number(roughness):
                raise TypeError(
                    cell_prefix + "roughness must be a non-bool int or float"
                )
            if not math.isfinite(roughness):
                raise ValueError(cell_prefix + "roughness must be finite")
            if not roughness >= 0:
                raise ValueError(cell_prefix + "roughness must be >= 0")

    for name, value in (("slope_limit", slope_limit), ("roughness_limit", roughness_limit)):
        if not _is_real_number(value):
            raise TypeError(f"{name} must be a non-bool int or float")
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")
        if not value > 0:
            raise ValueError(f"{name} must be > 0")

    result = []
    for r, nx, ny, analysis in layers:
        total = nx * ny
        valid = 0
        slope_exceed = 0
        roughness_exceed = 0
        for slope, roughness in analysis:
            if slope is None and roughness is None:
                continue
            valid += 1
            if slope is not None and slope > slope_limit:
                slope_exceed += 1
            if roughness > roughness_limit:
                roughness_exceed += 1
        result.append(
            {
                "resolution": _round6(r),
                "total": total,
                "valid": valid,
                "coverage": _round6(valid / total),
                "slope_exceed": slope_exceed,
                "roughness_exceed": roughness_exceed,
            }
        )
    return tuple(result)

"""Sound velocity profile (SVP) ray tracing.

Layered sound-speed model: layer ``i`` covers ``[z[i], z[i+1])`` with
sound speed ``c[i]``; the last layer extends downward without bound and
a boundary depth belongs to the deeper layer.
"""

from __future__ import annotations

import math

__all__ = ["trace"]


def _is_real_number(value: object) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _checked_profile(name: str, values: object) -> list[float]:
    if not isinstance(values, (list, tuple)):
        raise TypeError(f"{name} must be a list or tuple")
    if len(values) == 0:
        raise ValueError(f"{name} must be non-empty")
    for item in values:
        if not _is_real_number(item):
            raise TypeError(f"{name} elements must be non-bool int or float")
    result = list(values)
    for item in result:
        if not math.isfinite(item):
            raise ValueError(f"{name} elements must be finite")
    return result


def trace(z, c, a, t, z0=0.0):
    """Trace a ray through a layered sound velocity profile.

    ``z``/``c`` are equal-length non-empty lists/tuples of non-bool
    int/float: ``z[0] == 0``, strictly increasing, ``c`` all positive.
    ``a`` (degrees, ``0 <= a < 89``), ``t`` (two-way seconds, ``t > 0``)
    and ``z0`` (``z0 >= 0``) must share one type and all be finite.

    Returns ``(x, d)``: horizontal offset and depth after a one-way
    travel time of ``t / 2``, each rounded to 6 decimals.
    """
    zs = _checked_profile("z", z)
    cs = _checked_profile("c", c)
    if len(zs) != len(cs):
        raise ValueError("z and c must have equal length")
    if zs[0] != 0:
        raise ValueError("z[0] must be 0")
    for k in range(len(zs) - 1):
        if not zs[k] < zs[k + 1]:
            raise ValueError("z must be strictly increasing")
    for speed in cs:
        if not speed > 0:
            raise ValueError("c elements must be positive")

    for name, value in (("a", a), ("t", t), ("z0", z0)):
        if not _is_real_number(value):
            raise TypeError(f"{name} must be a non-bool int or float")
    if not (type(a) is type(t) is type(z0)):
        raise TypeError("a, t and z0 must have the same type")
    for name, value in (("a", a), ("t", t), ("z0", z0)):
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")
    if not 0 <= a < 89:
        raise ValueError("a must satisfy 0 <= a < 89")
    if not t > 0:
        raise ValueError("t must be positive")
    if not z0 >= 0:
        raise ValueError("z0 must be >= 0")

    d = float(z0)
    x = 0.0
    r = t / 2
    n = len(zs)

    i = 0
    for k in range(n):
        if zs[k] <= d:
            i = k
        else:
            break
    p = math.sin(math.radians(a)) / cs[i]

    while True:
        speed = cs[i]
        q = p * speed
        if q >= 1:
            raise ValueError("total internal reflection")
        vx = speed * q
        vz = speed * math.sqrt(1 - q * q)
        s = math.inf if i == n - 1 else (zs[i + 1] - d) / vz
        u = r if r <= s else s
        x += vx * u
        d += vz * u
        if r <= s:
            break
        r -= s
        i += 1

    xr = round(x, 6)
    dr = round(d, 6)
    return (0.0 if xr == 0 else xr, 0.0 if dr == 0 else dr)

